pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Initialize the contract
        c.initialize(address(0x1234));

        // Call proxiableUUID() and check it returns the expected value
        bytes32 expected = 0x360894a13ba1a3210667c828492db98dca3e2076cc3735a920a3ca505d382bbc;
        bytes32 actual = c.proxiableUUID();
        assertTrue(actual == expected, "proxiableUUID should return IMPLEMENTATION_SLOT");
    }
}

