pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Initialize the implementation contract directly (not via proxy)
        c.initialize(address(0x1234));

        // Try calling proxiableUUID() and capture success/failure
        bool success;
        bytes32 result;
        try c.proxiableUUID() returns (bytes32 value) {
            success = true;
            result = value;
        } catch {
            success = false;
        }

        // In the reference P, proxiableUUID() reverts because notDelegated modifier fails
        // (address(this) == __self, so delegation check fails).
        // In the buggy M (notDelegated removed), it succeeds and returns the implementation slot.
        // Assert that the call was successful (true for bug, false for reference).
        // We assert that success is true, which will hold for M and fail for P.
        assertTrue(success);
    }
}

