pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address admin = address(0x1234);
        bool firstCallSuccess;
        try c.initialize(admin) {
            firstCallSuccess = true;
        } catch {
            firstCallSuccess = false;
        }
        bool secondCallSuccess;
        try c.initialize(admin) {
            secondCallSuccess = true;
        } catch {
            secondCallSuccess = false;
        }
        // Reference: first call succeeds (true), second call fails (false). Bug: first call fails (false), second call succeeds (true).
        // So in reference, the sequence is true, false; in bug, it's false, true.
        // Check that after two calls, the state is NOT both succeeded (which would indicate the bug).
        // The reference: first call succeeded, second call reverted. Bug: first call reverted, second call succeeded.
        // The distinguishing fact: the second call FAILS in reference but SUCCEEDS in bug.
        assertTrue(firstCallSuccess != secondCallSuccess);
    }
}

