import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Call initialize with a dummy address (access control contract)
        address dummyAccessControl = address(0xdead);
        c.initialize(dummyAccessControl);
        // In the reference, _getInitializedVersion() returns 1 after initialization.
        // In the buggy version, it returns 0 because $._initialized was set to 0.
        // We assert that the version is 1; this holds for P and fails for M.
        // Note: _getInitializedVersion() is not public, but we can check the emitted event.
        // Since we cannot read private storage directly, we use a try/catch to detect revert.
        // However, the simplest observable difference is the public variable `paused`? No.
        // But we can observe the Initialized event emission: the buggy version emits Initialized(1)
        // even though _initialized is 0, because the emit after `_` still fires.
        // Both emit, so that doesn't diverge.
        // The property must be visible via a public view. Since _getInitializedVersion() is internal
        // and no public getter exists, we must use a different approach. Actually the contract has
        // no public getter for _initialized. But we can check that after initialization, the contract
        // allows reinitialization (which the reference forbids). In the reference, calling initialize
        // again reverts with InvalidInitialization. In the buggy version, it does not revert because
        // initialSetup will be true (initialized == 0). So we can detect divergence by attempting
        // a second initialization.
        vm.expectRevert(); // For reference, second call reverts
        c.initialize(dummyAccessControl);
        // Actually we need to assert on a boolean, not expectRevert directly.
        // Use try/catch:
        bool ok;
        try c.initialize(dummyAccessControl) {
            ok = true;
        } catch {
            ok = false;
        }
        // In the reference, ok == false (reverts). In the buggy, ok == true (succeeds).
        assertTrue(ok == false); // This assertion holds for P (revert => ok false) but fails for M (ok true)
    }
}

