        vault.setUtilization(0.6e27); // 60% utilization
        vault.setCurrentUtilizationIndex(1e27); // index = 1e27

        // Set initial utilizationData for this vault/asset by calling rate once
        // Before first call, utilizationData.lastUpdate = 0, utilizationData.index = 0
        // First call: block.timestamp > lastUpdate (0), elapsed = block.timestamp
